shop_a <- data.frame(item = c("mug", "tote"), sold = c(5, 3))
shop_b <- data.frame(sold = c(4, 6), item = c("mug", "poster"))
shop_c <- data.frame(item = "mug", sold = 2, price = 8.5)
stack_all <- function(pieces) {
  cols <- unique(unlist(lapply(pieces, names)))
  filled <- lapply(pieces, function(d) {
    d[setdiff(cols, names(d))] <- NA
    d[cols]
  })
  do.call(rbind, filled)
}
abc <- stack_all(list(shop_a, shop_b, shop_c))
